program='''def transform(grid):
    n = len(grid)
    out = [row[:] for row in grid]

    def orbit(r, c):
        return {
            (r, c), (r, n - 1 - c), (n - 1 - r, c),
            (n - 1 - r, n - 1 - c), (c, r), (c, n - 1 - r),
            (n - 1 - c, r), (n - 1 - c, n - 1 - r),
        }

    for r in range(n):
        for c in range(n):
            if grid[r][c] == 2:
                colors = {grid[a][b] for a, b in orbit(r, c) if grid[a][b] != 2}
                assert len(colors) == 1
                out[r][c] = colors.pop()
    return out
'''
